#include <stdio.h>
#include <stdlib.h>

#define MOD 1000000007LL

typedef struct {
    long long m, c;
} Line;

typedef struct {
    long long a, b;
} Meal;

int cmpLine(const void *a, const void *b) {
    Line *l1 = (Line*)a;
    Line *l2 = (Line*)b;
    if (l1->m != l2->m) return (l1->m < l2->m) ? -1 : 1;
    if (l1->c != l2->c) return (l1->c > l2->c) ? -1 : 1;
    return 0;
}

int cmpMeal(const void *a, const void *b) {
    Meal *u = (Meal*)a;
    Meal *v = (Meal*)b;
    if (u->a == 1 && v->a == 1) return 0;
    if (u->a == 1) return -1;
    if (v->a == 1) return 1;
    long long left = u->b * (v->a - 1);
    long long right = v->b * (u->a - 1);
    if (left > right) return -1;
    if (left < right) return 1;
    return 0;
}

long long modpow(long long base, long long exp) {
    long long res = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

int bad(Line l1, Line l2, Line l3) {
    long long left = (l1.c - l2.c) * (l3.m - l2.m);
    long long right = (l2.c - l3.c) * (l2.m - l1.m);
    return left >= right;
}

long long eval(Line l, long long x) {
    return l.m * x + l.c;
}

int main() {
    int N, M, Q;
    long long K;
    scanf("%d %d %lld", &N, &M, &K);

    long long *a_spells = malloc(N * sizeof(long long));
    long long *b_spells = malloc(N * sizeof(long long));
    for (int i = 0; i < N; i++) scanf("%lld", &a_spells[i]);
    for (int i = 0; i < N; i++) scanf("%lld", &b_spells[i]);

    Meal *meals = malloc(M * sizeof(Meal));
    for (int i = 0; i < M; i++) scanf("%lld", &meals[i].a);
    for (int i = 0; i < M; i++) scanf("%lld", &meals[i].b);

    scanf("%d", &Q);

    // Preprocess meals
    qsort(meals, M, sizeof(Meal), cmpMeal);
    long long A_meal = 1, B_meal = 0;
    for (int i = M - 1; i >= 0; i--) {
        long long a = meals[i].a % MOD;
        long long b = meals[i].b % MOD;
        B_meal = (B_meal + b * A_meal) % MOD;
        A_meal = (A_meal * a) % MOD;
    }

    // Spells
    long long max_a = 0, B_spell = 0, Bmax = 0;
    for (int i = 0; i < N; i++) {
        if (a_spells[i] > max_a) max_a = a_spells[i];
        if (b_spells[i] > Bmax) Bmax = b_spells[i];
    }
    for (int i = 0; i < N; i++) {
        if (a_spells[i] == max_a && b_spells[i] > B_spell) B_spell = b_spells[i];
    }

    Line *hull = NULL;
    int hull_cnt = 0;
    long long powA = 1, geom = 0;

    if (max_a > 1) {
        Line *lines = malloc(N * sizeof(Line));
        for (int i = 0; i < N; i++) {
            lines[i].m = a_spells[i];
            lines[i].c = b_spells[i];
        }
        qsort(lines, N, sizeof(Line), cmpLine);

        Line *unique = malloc(N * sizeof(Line));
        int uniq_cnt = 0;
        for (int i = 0; i < N; i++) {
            if (uniq_cnt > 0 && unique[uniq_cnt - 1].m == lines[i].m) continue;
            unique[uniq_cnt++] = lines[i];
        }

        hull = malloc(uniq_cnt * sizeof(Line));
        for (int i = 0; i < uniq_cnt; i++) {
            Line l = unique[i];
            while (hull_cnt >= 2 && bad(hull[hull_cnt - 2], hull[hull_cnt - 1], l)) {
                hull_cnt--;
            }
            hull[hull_cnt++] = l;
        }

        free(lines);
        free(unique);

        long long exp = K - 1;
        powA = modpow(max_a, exp);
        long long invA_minus1 = modpow(max_a - 1, MOD - 2);
        geom = (powA - 1 + MOD) % MOD * invA_minus1 % MOD;
    }

    for (int qi = 0; qi < Q; qi++) {
        long long x;
        scanf("%lld", &x);
        long long Y;
        if (max_a == 1) {
            Y = (x % MOD + (K % MOD) * (Bmax % MOD)) % MOD;
        } else {
            int lo = 0, hi = hull_cnt - 1;
            while (lo < hi) {
                int mid = (lo + hi) / 2;
                long long v1 = eval(hull[mid], x);
                long long v2 = eval(hull[mid + 1], x);
                if (v1 <= v2) lo = mid + 1;
                else hi = mid;
            }
            Line best = hull[lo];
            long long val = ((best.m % MOD) * (x % MOD) + (best.c % MOD)) % MOD;
            Y = (powA * val + (B_spell % MOD) * geom) % MOD;
        }
        long long ans = (A_meal * Y + B_meal) % MOD;
        printf("%lld\n", ans);
    }

    free(a_spells);
    free(b_spells);
    free(meals);
    if (hull) free(hull);
    return 0;
}
